TEXT["translator-complaints"] = {
    "path": "de/uebersetzer-abo-ohne-ueberraschungen-offline-probleme-iphone/",
    "kicker": "Übersetzer-Leitfaden",
    "title": "Alternativen zu Translate Now ohne unerwartetes Abo (2026)",
    "h1": "Alternativen zu Translate Now ohne unerwartetes Abo (2026)",
    "description": "Übersetzer-Apps erhalten 1- und 2-Sterne-Bewertungen zu Abos und Abbuchungen, zum Offline-Modus, der nicht funktioniert, und zu Netzwerkfehlern. Was 157 aktuelle Bewertungen von vier Übersetzer-Apps sagen und wie Sie jede vor dem Bezahlen prüfen.",
    "llms": "Leitfaden, 15. November 2026: die drei Beschwerden, die sich in 157 aktuellen 1- und 2-Sterne-Bewertungen im App Store zu Translate Now, Google Translate, Microsoft Translator und iTranslate am häufigsten wiederholen: Abos und Abbuchungen nach der Kündigung (fast die Hälfte der Bewertungen zu Translate Now), der Offline-Modus, der nicht wie angekündigt funktioniert, und Netzwerkfehler. Zu jeder gibt es eine Prüfung, die Sie vor dem Herunterladen oder einer Reise machen können. Die Zahlen sind ungefähr.",
    "stand": "Beschwerden aus 157 aktuellen App-Store-Bewertungen von vier Übersetzer-Apps und eine Prüfung, die Sie vor dem Bezahlen oder einer Reise machen können.",
    "answer": [
        "<strong>Um einen Übersetzer ohne unerwartetes Abo zu wählen, lesen Sie vor dem Download die Bedingungen für Testphase und Verlängerung auf seiner App-Store-Seite, setzen Sie eine Erinnerung für den Tag, an dem die Testphase endet, und wissen Sie, wo Sie kündigen: Einstellungen, Ihr Name, Abonnements.</strong> Testen Sie den Offline-Modus zu Hause, bevor Sie verreisen, denn mehrere Apps versagen dort.",
        "In 157 1- und 2-Sterne-Bewertungen zu Translate Now, Google Translate, Microsoft Translator und iTranslate waren Abos und Abbuchungen am häufigsten (vor allem bei Translate Now), gefolgt vom Offline-Modus, der nicht wie erwartet funktioniert, und Netzwerkfehlern. Zu jeder gibt es unten eine Prüfung.",
    ],
    "sections": [
        ["data", "Was wir uns angesehen haben",
         "<p>Wir haben die neuesten 1- und 2-Sterne-Bewertungen von vier Übersetzer-Apps aus dem US-App-Store heruntergeladen: <a href='" + _DE_TN + "'>Translate Now - AI Translator</a> (30 Bewertungen), <a href='" + _DE_GT + "'>Google Translate</a> (55), <a href='" + _DE_MT + "'>Microsoft Translator</a> (57) und <a href='" + _DE_IT + "'>iTranslate Translator</a> (15). Das sind 157 Bewertungen insgesamt, jeweils die neuesten jeder App (bis zu 100 pro App), heruntergeladen am 15. November 2026. Drei Gruppen tauchen immer wieder auf: Geld (Abos, Bezahlschranken, Abbuchungen nach der Kündigung), der Offline-Modus, der nicht wie erwartet funktioniert, und Netzwerkfehler.</p>\n<ul>\n<li>Abos, Bezahlschranken und Abbuchungen: fast die Hälfte der Bewertungen zu Translate Now (14 von 30) und 4 von 15 bei iTranslate.</li>\n<li>Offline- oder „kein Internet“-Probleme: 5 von 55 bei Google Translate und 6 von 57 bei Microsoft Translator.</li>\n<li>Falsche oder schlechte Übersetzungen: 10 von 55 bei Google Translate.</li>\n</ul>\n<p>Bewertungen sind die Meinungen unzufriedener Menschen. Sie sind kein Test der Apps.</p>\n"],
        ["money", "„Trotz Kündigung abgebucht“ und die Testphase (die größte Gruppe)",
         "<p>Das ist die größte Gruppe bei Translate Now. Ein Bewerter: „I canceled the subscription and it still charged me“ (Translate Now, 1 Stern). Ein anderer: „Did not realize they were taking $10.98 a WEEK on a subscription fee“ (Translate Now, 1 Stern). Bei iTranslate geht es um die Testphase: „Be sure to cancel after trial or pay $40 per month every month!“ (iTranslate, 1 Stern). Manche finden den kostenlosen Teil zu klein: „You have to pay for common languages“ (Translate Now, 1 Stern). Das sind die Worte der Bewerter, keine Fakten, die wir in jeder App geprüft haben.</p>\n<p>Die App-Store-Seiten sagen, was jede App verkauft. Die Seite von Translate Now bewirbt ein Abo namens Air Apps One. Die Seite von iTranslate sagt, dass eine kostenlose Testphase in ein kostenpflichtiges Abo übergeht, sofern die automatische Verlängerung nicht mindestens 24 Stunden vor Ende der Testphase ausgeschaltet wird.</p>\n<p><strong>Vorgehen, bevor Sie herunterladen und bevor Sie eine Testphase starten:</strong></p>\n<ol>\n<li>Scrollen Sie auf der App-Store-Seite ganz nach unten und lesen Sie die Abo-Bedingungen: den Preis, wie oft er sich verlängert und wann eine kostenlose Testphase endet.</li>\n<li>Setzen Sie eine Kalendererinnerung für den Tag vor dem Ende der Testphase.</li>\n<li>Zum Prüfen oder Beenden eines Abos: Öffnen Sie Einstellungen, tippen Sie auf Ihren Namen, auf Abonnements, auf das Abo und dann auf Abo kündigen. Die Schritte von Apple stehen unter <a href='" + _DE_CANCEL + "'>Abo bei Apple kündigen</a>. Das Löschen der App kündigt das Abo nicht.</li>\n<li>Wenn Sie trotz Kündigung abgebucht wurden, können Sie Apple um eine Erstattung bitten: <a href='" + _DE_REFUND + "'>Erstattung für Apps oder Inhalte anfordern, die Sie bei Apple gekauft haben</a>. Apple entscheidet.</li>\n</ol>\n"],
        ["offline", "„Funktioniert offline nicht“ (Google Translate, Microsoft Translator)",
         "<p>Ein Übersetzer ist dann am nützlichsten, wenn kein Empfang besteht: im Flugzeug oder in der U-Bahn einer fremden Stadt. Die Bewertungen sagen, dass dann mehrere Apps versagen. Ein Bewerter von Google Translate: „It DOES NOT work offline as advertised…“ (1 Stern). Ein anderer, aus Japan: „This app was unusable if /when I wasn't connected to the internet“ (2 Sterne). Ein Bewerter von Microsoft Translator schreibt, die App habe „removed the ability to download languages for offline use“ (1 Stern).</p>\n<p>Die App-Store-Seite von iTranslate sagt dasselbe von ihrer Seite: Für den Offline-Modus müssen Sprachpakete zuerst heruntergeladen werden.</p>\n<p><strong>Vorgehen:</strong> Testen Sie den Offline-Modus zu Hause im WLAN, bevor Sie reisen. Schalten Sie WLAN und mobile Daten aus, öffnen Sie die App und übersetzen Sie einen Satz. Schlägt das fehl, fehlt das Sprachpaket oder die App bietet für diese Sprache keinen Offline-Modus. Suchen Sie in den Einstellungen der App nach herunterladbaren Sprachen; finden Sie sie nicht, sehen Sie zuerst auf der App-Store-Seite nach.</p>\n"],
        ["network", "„Netzwerkfehler“ (Microsoft Translator)",
         "<p>Microsoft Translator hat in dieser Auswahl die meisten Netzwerkbeschwerden, vor allem beim Live-Gesprächsmodus: „Keeps getting network error when trying to use live translation“ (2 Sterne), von einem Bewerter, der im WLAN war. Ein anderer Bewerter sagt, die App habe ihn aufgefordert, das Netzwerk zu prüfen, obwohl er im WLAN war.</p>\n<p><strong>Vorgehen:</strong> Schließen Sie die App ganz, schalten Sie WLAN aus und wieder ein und probieren Sie es mit mobilen Daten. Schlägt es weiter fehl, nutzen Sie den Textmodus: Er ist langsamer, funktioniert aber oft. Brauchen Sie einen verlässlichen Offline-Modus, entscheiden Sie das vor der Reise, nicht mitten in einem Gespräch.</p>\n"],
        ["checklist", "Vor dem Herunterladen oder der Reise: eine Prüfung in 5 Punkten",
         "<ul>\n<li>Habe ich vor dem Download die Abo-Bedingungen und die Länge der Testphase auf der App-Store-Seite gelesen?</li>\n<li>Habe ich eine Erinnerung für den Tag vor Ende der Testphase gesetzt?</li>\n<li>Habe ich den Offline-Modus zu Hause getestet, mit ausgeschaltetem WLAN und mobilen Daten?</li>\n<li>Habe ich geprüft, welche Sprachen ich herunterladen kann und ob ich sie vor der Abreise brauche?</li>\n<li>Weiß ich, wo ich kündigen kann (<a href='" + _DE_CANCEL + "'>Apple: Abo kündigen</a>) und wie ich eine Erstattung anfordere (<a href='" + _DE_REFUND + "'>Apple: Erstattung anfordern</a>)?</li>\n</ul>\n"],
    ],
    "faq": [
        ["Welche Übersetzer-App hat am wenigsten Abo-Beschwerden?",
         "Die Bewertungen nennen keinen Sieger. In dieser Auswahl hatte Translate Now die meisten Beschwerden über Abos und Abbuchungen (14 von 30 aktuellen 1- und 2-Sterne-Bewertungen). Lesen Sie vor dem Download die Abo-Bedingungen jeder App im App Store."],
        ["Funktioniert Google Translate auf dem iPhone offline?",
         "Einige Bewerter sagen, dass es offline nicht wie angekündigt funktioniert. Testen Sie es zu Hause, mit ausgeschaltetem WLAN und mobilen Daten, vor einer Reise, und prüfen Sie, welche Sprachen Sie herunterladen können."],
        ["Wie kündige ich ein Abo für eine Übersetzer-App?",
         "Auf dem iPhone: Öffnen Sie Einstellungen, tippen Sie auf Ihren Namen, auf Abonnements, auf das Abo und dann auf Abo kündigen. Apple erklärt das auf seiner Seite zur Kündigung eines Abos."],
        ["Kann ich eine Abbuchung nach der Kündigung zurückbekommen?",
         "Sie können Apple darum bitten. Auf der Seite von Apple zur Erstattung für Apps oder Inhalte, die bei Apple gekauft wurden, steht, wie das geht; die Entscheidung trifft Apple."],
    ],
    "sources_html": [
        "Bewertungen: Kundenbewertungs-Feed des US-App-Stores, jeweils die neueste Seite jeder App, 157 Bewertungen mit 1–2 Sternen, heruntergeladen am 15. November 2026; Zählung nach Stichwörtern, ungefähr.",
        "Apps: US-App-Store-Seiten und Apple-Abfragedaten zu Translate Now, Google Translate, Microsoft Translator und iTranslate, Stand 15. November 2026.",
        "<a href='" + _DE_CANCEL + "'>Abo bei Apple kündigen</a>, Apple Support.",
        "<a href='" + _DE_REFUND + "'>Erstattung für Apps oder Inhalte anfordern, die Sie bei Apple gekauft haben</a>, Apple Support.",
    ],
    "fix": "Wenn etwas auf dieser Seite veraltet ist, <a href='mailto:sagalabs@proton.me'>sagen Sie uns Bescheid</a>, und wir korrigieren die Seite.",
    "not_on_sale": "{names} ist im deutschen App Store nicht erhältlich: der Name steht ohne Link, die Daten stammen aus der US-Seite.",
}

